static int logq_cmp(ogg_int16_t(*a)[3][2],ogg_int16_t(*b)[3][2]){
  int pli;
  int qti;
  int qi;
  for(pli=0;pli<3;pli++){
    for(qti=0;qti<2;qti++){
      for(qi=0;qi<OC_LOGQ_BINS-1;qi++){
        if(a[qi][pli][qti]!=b[qi][pli][qti]){
          return EXIT_FAILURE;
        }
      }
    }
  }
  return EXIT_SUCCESS;
}
